-- Introductions par livre (les 66), tirees du panorama de l'auteur
-- ("DECODER LA BIBLE") : ou on se situe, qui, pourquoi, le fil vers Christ,
-- et un verset-cle. Colonnes alignees sur ce qu'attend app/lire + Reader.

create table if not exists book_intros (
  book int primary key,           -- correspond a books.id (1-66)
  name text not null,
  title text not null,            -- titre memorable du livre
  section text not null,          -- groupe (Pentateuque, Prophetes majeurs...)
  testament text not null,        -- 'AT' | 'NT'
  situ text not null,             -- ou on se situe dans le fil
  who text not null,              -- qui
  why text not null,              -- pourquoi ce livre
  christ text not null,           -- le fil rouge vers Jesus
  key_verse text,                 -- verset-cle a ouvrir
  created_at timestamptz default now()
);

alter table book_intros enable row level security;
drop policy if exists pub_book_intros on book_intros;
create policy pub_book_intros on book_intros for select using (true);

on conflict (book) do update set
  name = excluded.name, title = excluded.title, section = excluded.section,
  testament = excluded.testament, situ = excluded.situ, who = excluded.who,
  why = excluded.why, christ = excluded.christ, key_verse = excluded.key_verse;
